    // SCENARIO 8: Scanned PDF detection
    it("Scenario 8: Identifies scanned or image-based PDF and issues visual extraction warning", async () => {
        // Mock a 50KB PDF buffer containing almost no text layer (e.g. scanned image document)
        const fakePdfBytes = new Uint8Array(60000);
        // Put PDF magic bytes at start: %PDF-
        fakePdfBytes[0] = 0x25; fakePdfBytes[1] = 0x50; fakePdfBytes[2] = 0x44; fakePdfBytes[3] = 0x46; fakePdfBytes[4] = 0x2D;
        const fakeFile = new File([fakePdfBytes], "scanned_invoice.pdf", { type: "application/pdf" });

        const result = await parseResumePipeline({
            file: fakeFile,
            fileName: "scanned_invoice.pdf"
        });

        expect(result.isScanned).toBe(true);
        expect(result.warnings.some(w => w.code === "SCANNED_PDF_DETECTED" || w.code === "PDF_PARSE_WARNING")).toBe(true);
    });

